-- 站点文案
INSERT OR IGNORE INTO settings (key, value, updated_at) VALUES ('brand', '{"name":"稳链同创","legalName":"稳链投资控股（海南）有限公司","nameEn":"WENLIAN TONGCHUANG","tagline":"稳健为本 · 同创共赢","description":"稳链投资控股（海南）有限公司 —— 以长期主义经营伙伴关系的产业投资控股平台。","logo":"assets/img/logo.png","logoMark":"assets/img/logo-mark.png"}', '2026-09-01T00:00:00.000Z');
INSERT OR IGNORE INTO settings (key, value, updated_at) VALUES ('hero', '{"eyebrow":"稳链投资控股（海南）有限公司","title":"稳链同创","subtitle":"以长期主义经营伙伴关系，把每一次合作沉淀为可交付的项目、可核对的账目。","primaryCta":{"text":"了解我们的理念","href":"#philosophy"},"secondaryCta":{"text":"联系我们","href":"#contact"}}', '2026-09-01T00:00:00.000Z');
INSERT OR IGNORE INTO settings (key, value, updated_at) VALUES ('about', '{"title":"关于我们","subtitle":"一家把伙伴关系当作长期资产来经营的产业投资控股平台","paragraphs":["稳链投资控股（海南）有限公司注册于海南自由贸易港，以「稳链同创」为业务品牌，专注于产业链上下游的协同投资与运营。我们不做短周期的机会型交易，只与看得懂的行业、信得过的伙伴建立长期关系。","在合作方式上，我们既是出资方，也是共同经营者。从立项、签约、执行到结项，每一个阶段都有明确的负责人、时间节点与结算口径；每一笔资金往来都逐笔留痕、可随时核对。让合作双方在任何时点都能对同一份事实达成共识，是我们认为最重要的基础设施。"],"highlights":[{"icon":"◆","title":"长期主义","desc":"以年为单位衡量合作，不用短期指标透支伙伴关系。"},{"icon":"◈","title":"权责清晰","desc":"分工、节点、收益分配在合作之初就写进白纸黑字。"},{"icon":"◇","title":"账目透明","desc":"收付款计划与实际结算逐笔登记，双方口径一致。"},{"icon":"❖","title":"共担共享","desc":"风险共同承担，增量共同分享，不做零和博弈。"}]}', '2026-09-01T00:00:00.000Z');
INSERT OR IGNORE INTO settings (key, value, updated_at) VALUES ('philosophy', '{"title":"经营理念","subtitle":"「稳链同创」四个字，就是我们做事的四条准则","statement":"我们相信，稳固的关系比漂亮的条款更有价值；能长久走下去的合作，从来不是靠一次谈判赢来的。","items":[{"char":"稳","title":"稳健为先","desc":"不追风口，不赌趋势。只投资看得懂的生意、只承接算得清的项目，把风险控制放在收益预期之前。"},{"char":"链","title":"链接价值","desc":"把上下游分散的能力连成闭环，让每个环节的优势都能被下一个环节接住，价值在链条上流动而非停滞。"},{"char":"同","title":"同舟共济","desc":"与伙伴站在同一条船上。顺境时不独占，逆境时不脱身，用共担风险换取真正的信任。"},{"char":"创","title":"创造增量","desc":"合作的意义在于做大蛋糕，而不是重新切分。我们只做能创造新增量的事，拒绝零和分配。"}]}', '2026-09-01T00:00:00.000Z');
INSERT OR IGNORE INTO settings (key, value, updated_at) VALUES ('stats', '[{"label":"深耕行业","value":8,"suffix":"年"},{"label":"长期合作伙伴","value":30,"suffix":"+"},{"label":"累计投资规模","value":12,"suffix":"亿"},{"label":"合作续约率","value":92,"suffix":"%"}]', '2026-09-01T00:00:00.000Z');
INSERT OR IGNORE INTO settings (key, value, updated_at) VALUES ('contact', '{"title":"成为我们的伙伴","subtitle":"如果你的业务与我们的链条相关，欢迎联系洽谈。","company":"稳链投资控股（海南）有限公司","email":"support@partnerrealm.com","phone":"18347348633","workTime":"工作日 09:00 - 18:00"}', '2026-09-01T00:00:00.000Z');
INSERT OR IGNORE INTO settings (key, value, updated_at) VALUES ('footer', '{"copyright":"© 2026 稳链投资控股（海南）有限公司 版权所有","icp":""}', '2026-09-01T00:00:00.000Z');

